import sys
import os
import json
from dotenv import load_dotenv

sys.path.insert(0, '.')
load_dotenv('.env')

from backend.core.orchestrator import execute_plan
from backend.mcp_core.mcp_client import close_mcp_client

def main():
    print("=== Testing Orchestrator Dependency Resolution ===")
    
    # We will simulate a plan generated by an LLM that reads a CSV from Google Drive
    # and then feeds its coordinates into the Flood Risk tool.
    
    # 1rq9aGbuAgHe3rmZzfqemWw-Q2xEEjfMd is 'Ubicacion_estaciones_segura.csv'
    
    mock_plan = [
        {
            "tool": "drive_read_sheet",
            "arguments": {
                "file_id": "1rq9aGbuAgHe3rmZzfqemWw-Q2xEEjfMd",
                "row_limit": 1
            }
        },
        {
            "tool": "patricova_flood_risk",
            "arguments": {
                "lat": "$STEP_0.data.0.lat",
                "lon": "$STEP_0.data.0.lon"
            }
        }
    ]
    
    print("Mock Plan:")
    print(json.dumps(mock_plan, indent=2))
    
    print("\nExecuting...")
    results = execute_plan(mock_plan)
    
    print("\n=== Execution Results ===")
    for i, res in enumerate(results):
        print(f"--- STEP {i} ({res.get('tool')}) ---")
        print("Arguments used:", res.get("arguments"))
        status = res.get("result", {}).get("status") if isinstance(res.get("result"), dict) else "Unknown"
        print("Status:", status)
        
        # Print a snippet of the result to keep it clean
        if i == 0:
            data = res.get("result", {}).get("data", [])
            print("First row fetched:", data[0] if data else "None")
        elif i == 1:
            print("Flood Risk Data:", res.get("result", {}).get("data"))

    close_mcp_client()

if __name__ == "__main__":
    main()
